void recur(const vector<long long>& a, int l, int r, vector<long long>& out, long long c) {

    function<void(int,long long)> dfs = [&](int idx, long long cur) {
        if (cur > c) return; 
        if (idx == r) {
            out.push_back(cur);
            return;
        }

        dfs(idx+1, cur);

        dfs(idx+1, cur + a[idx]);
    };
    dfs(l, 0);
}

int main() {

    int n;
    long long c;
    cin >> n >> c;
    vector<long long> w(n);
    for (int i = 0; i < n; ++i) cin >> w[i];

    vector<long long> a;
    a.reserve(n);
    for (int i = 0; i < n; ++i) if (w[i] <= c) a.push_back(w[i]);
    int k = (int)a.size();
    if (k == 0) {
        cout << 0 << '\n';
        return 0;
    }

    const int thing = 46; 
    if (k > thing) {

        set<long long> sums;
        sums.insert(0);
        for (int i = 0; i < k; ++i) {
            vector<long long> add;
            for (auto s : sums) {
                long long ns = s + a[i];
                if (ns <= c) add.push_back(ns);
            }
            for (auto ns : add) sums.insert(ns);

            if ((int)sums.size() > (1<<20)) { 

                long long total = 0;
                for (int j = k-1; j >= 0; --j)
                    if (total + a[j] <= c) total += a[j];
                cout << total << '\n';
                return 0;
            }
        }
        auto it = prev(sums.end());
        cout << *it << '\n';
        return 0;
    }

    int mid = k / 2;
    vector<long long> s1, s2;
    s1.reserve(1 << min(mid, 25)); 
    s2.reserve(1 << min(k-mid, 25));

    recur(a, 0, mid, s1, c);
    recur(a, mid, k, s2, c);

    sort(s2.begin(), s2.end());

    long long best = 0;
    for (long long x : s1) {
        if (x > c) continue;
        long long rem = c - x;

        auto it = upper_bound(s2.begin(), s2.end(), rem);
        if (it == s2.begin()) {

            best = max(best, x);
        } else {
            --it;
            best = max(best, x + *it);
        }
        if (best == c) break; 
    }

    cout << best;
}